/**
 * UGM letterhead logo for the consent PDF, inlined as a data URI.
 * Inlined rather than read from `public/` at runtime: @react-pdf/renderer runs
 * server-side and the deployed lambda cannot be relied on to have public/ on disk.
 * Regenerate: sips -s format png -Z 320 <source>.jpg --out public/ugm-logo.png && base64 -i public/ugm-logo.png
 */
export const UGM_LOGO_DATA_URI = 'data:image/png;base64,'
